#include "gemm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize the arrays A, B, C exactly as in the original C code,
 * but using Halide Funcs and Buffers instead of raw C arrays.
 *
 * Original C loops:
 *   *alpha = 1.5;
 *   *beta  = 1.2;
 *   for (i = 0; i < ni; i++)
 *     for (j = 0; j < nj; j++)
 *       C[i][j] = ((i*j+1) % ni) / ni;
 *   for (i = 0; i < ni; i++)
 *     for (j = 0; j < nk; j++)
 *       A[i][j] = (i*(j+1) % nk) / nk;
 *   for (i = 0; i < nk; i++)
 *     for (j = 0; j < nj; j++)
 *       B[i][j] = (i*(j+2) % nj) / nj;
 *
 * Mapping to Halide:
 *   - C[i][j]  (C is NI x NJ)  -> Buffer C(j, i)  of shape (nj, ni)
 *   - A[i][j]  (A is NI x NK)  -> Buffer A(k, i)  of shape (nk, ni)
 *   - B[i][j]  (B is NK x NJ)  -> Buffer B(j, k)  of shape (nj, nk)
 */
static void init_array(int ni, int nj, int nk,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j"), k("k");
    Func init_A("init_A"), init_B("init_B"), init_C("init_C");

    // Use Expr versions of the constants so we don't re-wrap ints repeatedly.
    Expr ni_e = ni;
    Expr nj_e = nj;
    Expr nk_e = nk;

    // C[i][j] = ((i*j+1) % ni) / ni;
    // Buffer layout: C(j, i)
    {
        Expr numer = (i * j + 1) % ni_e;
        init_C(j, i) = cast<num_t>(numer) / cast<num_t>(ni_e);
    }

    // A[i][j] = (i*(j+1) % nk) / nk;
    // Buffer layout: A(k, i) where k is the "j" from the C code
    {
        Expr numer = (i * (k + 1)) % nk_e;
        init_A(k, i) = cast<num_t>(numer) / cast<num_t>(nk_e);
    }

    // B[i][j] = (i*(j+2) % nj) / nj;
    // Buffer layout: B(j, k) where i in C code is our k, and j is j
    {
        Expr numer = (k * (j + 2)) % nj_e;
        init_B(j, k) = cast<num_t>(numer) / cast<num_t>(nj_e);
    }

    // --------------------------------------------------------------------
    // Initialize with a simple but reasonably optimized schedule:
    //  - compute each initializer at root
    //  - parallelize the outer (row) dimension
    //  - vectorize across the innermost (contiguous) dimension
    // --------------------------------------------------------------------
    Target t = get_host_target();
    int vec_width = t.natural_vector_size(type_of<num_t>());
    if (vec_width <= 0) {
        vec_width = 1;
    }

    // C: shape (nj, ni), layout C(j, i) – j is contiguous
    init_C
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // A: shape (nk, ni), layout A(k, i) – k is contiguous
    init_A
        .compute_root()
        .parallel(i)
        .vectorize(k, vec_width);

    // B: shape (nj, nk), layout B(j, k) – j is contiguous
    init_B
        .compute_root()
        .parallel(k)
        .vectorize(j, vec_width);

    // Realize initialization into the provided buffers
    init_C.realize(C);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem sizes (as in PolyBench)
    int ni = NI;
    int nj = NJ;
    int nk = NK;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    //   C: NI x NJ => (width = nj, height = ni)
    //   A: NI x NK => (width = nk, height = ni)
    //   B: NK x NJ => (width = nj, height = nk)
    Halide::Buffer<num_t, 2> C(nj, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> A(nk, ni);

    // ImageParams to represent the input/output images for the Halide pipeline.
    // They share the same logical layout as the Buffers above.
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    // Initialize data as in the original C code.
    init_array(ni, nj, nk, &alpha, &beta, C, A, B);

    // Define Vars
    Var i("i"), j("j");

    // Reduction domain over k = 0..nk-1 (the shared dimension of A and B)
    RDom k(0, nk, "k");

    // Main GEMM computation:
    //
    // Original C kernel:
    //
    // for (i = 0; i < ni; i++) {
    //   for (j = 0; j < nj; j++)
    //       C[i][j] *= beta;
    //   for (k = 0; k < nk; k++) {
    //      for (j = 0; j < nj; j++)
    //         C[i][j] += alpha * A[i][k] * B[k][j];
    //   }
    // }
    //
    // This is equivalent to:
    //   C[i][j] = beta * C[i][j] +
    //             sum_{k=0..nk-1}(alpha * A[i][k] * B[k][j]);
    //
    // Mapping to Halide coordinates:
    //   C(i,j) => C_param(j, i)
    //   A(i,k) => A_param(k, i)
    //   B(k,j) => B_param(j, k)
    //
    // We'll implement C := beta*C + alpha*A*B using a reduction.
    Func gemm("gemm");

    // Pure definition: initialize each output element with beta * C
    gemm(j, i) = Expr(beta) * C_param(j, i);

    // Update definition: accumulate alpha * A * B over k
    gemm(j, i) += Expr(alpha) * A_param(k, i) * B_param(j, k);

    // --------------------------------------------------------------------
    // Optimized schedule for GEMM
    //
    // Memory layout:
    //   - C(j, i)  : j (columns) is contiguous in memory.
    //   - A(k, i)  : k is contiguous.
    //   - B(j, k)  : j is contiguous.
    //
    // We:
    //   * compute gemm at root
    //   * tile the (j,i) output space for better cache locality
    //   * parallelize across tiles
    //   * vectorize across j (contiguous dimension)
    //   * use the same tiling for both pure and update stages so that
    //     data access patterns match nicely.
    // --------------------------------------------------------------------
    Target t = get_host_target();
    int vec_width = t.natural_vector_size(type_of<num_t>());
    if (vec_width <= 0) {
        vec_width = 1;
    }

    // Tunable tile sizes; chosen to be cache-friendly on modern x64.
    const int tile_j = 128;  // columns per tile (vectorized dimension)
    const int tile_i = 64;   // rows per tile

    Var jo("jo"), ji("ji"), io("io"), ii("ii");
    Var tile_index("tile_index");

    // Compute the entire result at root.
    gemm.compute_root();

    // Tile the output: (j,i) -> (jo,io) are tile indices, (ji,ii) are intra-tile.
    gemm
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        // Fuse the two tile indices into a single dimension so we can
        // parallelize over 2D tiles with a single parallel loop.
        .fuse(jo, io, tile_index)
        .parallel(tile_index)
        // Vectorize across j (columns), which is contiguous in memory.
        .vectorize(ji, vec_width);

    // Apply a consistent tiling and parallelization strategy to the
    // reduction update. This keeps the loops over (j,i) identical,
    // and parallelizes over tiles of independent outputs.
    gemm.update()
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        .fuse(jo, io, tile_index)
        .parallel(tile_index)
        .vectorize(ji, vec_width);
    // Note: we keep the k-loop innermost for each (i,j); each thread
    // accumulates independently for its tile, so there are no races.

    // Bind the ImageParams to the concrete Buffers
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // Compile the kernel to machine code (JIT)
    gemm.compile_jit();

    // Measure execution time of the GEMM kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write the result into C
    gemm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the resulting C, similar to PolyBench's print_array.
    // Here we just print all values to stderr when invoked with any argv[0] (always true),
    // but keep the check to mirror the example structure.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nj; jj++) {
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    // Print timing in seconds to stdout
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
