          .parallel(i)
          .vectorize(j, vec_width);

    // A(k, i): k is contiguous, i is outer
    init_A.compute_root()
          .parallel(i)
          .vectorize(k, vec_width);

    // B(j, k): j is contiguous, k is outer
    init_B.compute_root()
          .parallel(k)
          .vectorize(j, vec_width);

