    init_array(ni, nj, nk, &alpha, &beta, C, A, B);

    // Bind the ImageParams to the concrete Buffers
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // Define Vars
    Var i("i"), j("j");

    // Reduction domain over k = 0..nk-1 (the shared dimension of A and B)
    // Use the concrete buffer extent for robustness.
    RDom r(0, A.dim(0).extent(), "r");
    RVar k_r = r.x;  // Name for the reduction variable over k

    // ---------------------------
    // Optimized GEMM computation
    // ---------------------------
    //
    // Original C kernel:
    //
    // for (i = 0; i < ni; i++) {
    //   for (j = 0; j < nj; j++)
    //       C[i][j] *= beta;
    //   for (k = 0; k < nk; k++) {
    //      for (j = 0; j < nj; j++)
    //         C[i][j] += alpha * A[i][k] * B[k][j];
    //   }
    // }
    //
    // This is equivalent to:
    //   C[i][j] = beta * C[i][j] +
    //             sum_{k=0..nk-1}(alpha * A[i][k] * B[k][j]);
    //
    // Mapping to Halide coordinates:
    //   C(i,j) => C_param(j, i)
    //   A(i,k) => A_param(k, i)
    //   B(k,j) => B_param(j, k)
    //
    // To improve locality and enable more aggressive scheduling,
    // we factor the computation into two stages:
    //
    //   1) prod(j,i) = sum_k A_param(k,i) * B_param(j,k);
    //   2) gemm(j,i) = alpha * prod(j,i) + beta * C_param(j,i);
    //
