    // memory by ~33% relative to A/B/C for typical square problems,
    // staying within the requested +50% bound, but allows a very
    // regular, cache- and vector-friendly schedule.

    Func prod("prod");  // Holds A*B
    Func gemm("gemm");  // Final scaled C := beta*C + alpha*(A*B)

    // Stage 1: Matrix product prod = A * B
    prod(j, i) = cast<num_t>(0);
    prod(j, i) += A_param(k_r, i) * B_param(j, k_r);

    // Stage 2: Scale and accumulate into C
    gemm(j, i) = cast<num_t>(alpha) * prod(j, i) +
                 cast<num_t>(beta)  * C_param(j, i);

    // ---------------------------
    // Scheduling for performance
    // ---------------------------

    Target target = get_host_target();
    const int vec_width = natural_vector_size<num_t>(target);

    // Tunable tiling parameters for cache blocking. For large problems
    // (e.g., 1024x1024), 64x64 tends to work well on modern x86-64.
    const int TILE_I = 64;  // Tile size along the i (row) dimension
    const int TILE_J = 64;  // Tile size along the j (column) dimension

    // Tile indices and intra-tile coordinates
    Var io("io"), jo("jo"), ii("ii"), ji("ji");

    // ---- Schedule for prod (matrix product A*B) ----
    //
    // We compute prod at the root once, tiled in 2D, parallelized
    // across row tiles, and vectorized across the innermost j (columns).
    //
    // The reduction is fully local to each (i,j) element, so splitting
    // and parallelizing over tiles is safe (no write conflicts across
    // tiles).
    prod
        .compute_root()
        .tile(j, i, jo, io, ji, ii, TILE_J, TILE_I)
        .reorder(ji, ii, jo, io)     // j (columns) fastest, then i (rows)
        .vectorize(ji, vec_width)    // vectorize across contiguous columns
        .parallel(io);               // parallelize over row-tiles

    // Reorder the update (reduction) to keep the inner loops over
    // contiguous memory and the reduction variable next.
    prod.update()
        .reorder(ji, ii, k_r, jo, io)
        .vectorize(ji, vec_width);

    // ---- Schedule for gemm (final scaling and accumulation) ----
    //
    // gemm is a simple pointwise map over prod and C, so we reuse the
    // same 2D tiling pattern, with vectorization in j and parallelism
    // in tiles of i.
    gemm
        .compute_root()
        .tile(j, i, jo, io, ji, ii, TILE_J, TILE_I)
        .reorder(ji, ii, jo, io)
        .vectorize(ji, vec_width)
        .parallel(io);

    // Compile the kernel to machine code (JIT) for the selected target.
    gemm.compile_jit(target);

    // ---------------------------
    // Timing + execution
    // ---------------------------

    // Measure execution time of the GEMM kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write the result into C
    gemm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the resulting C, similar to PolyBench's print_array.
